n = int(input("How many numbers? "))

if n <= 0:
    print("Invalid number of values")
else:
    number = int(input("Enter number 1: "))
    maximum = number
    minimum = number

    for i in range(2, n + 1):
        number = int(input(f"Enter number {i}: "))
        if number > maximum:
            maximum = number
        if number < minimum:
            minimum = number

    print("Maximum:", maximum)
    print("Minimum:", minimum)
